Mesh<Point, double> mesh;
std::map<RT::Cell_handle, Point> dual_vertices;

// Collect dual vertices for all finite cells
for (RT::Finite_cells_iterator cit = rt.finite_cells_begin(); cit != rt.finite_cells_end(); ++cit) {
    dual_vertices[cit] = rt.dual(cit);
}

// Iterate over finite facets
for (RT::Finite_facets_iterator fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    RT::Facet f = *fit;

    if (!is_large_facet(rt, f, threshold)) {
        continue;
    }

    RT::Cell_handle c1 = f.first;
    RT::Cell_handle c2 = c1->neighbor(f.second);

    if (rt.is_infinite(c1) || rt.is_infinite(c2)) {
        continue;
    }

    Point p1 = dual_vertices[c1];
    Point p2 = dual_vertices[c2];

    mesh.add_edge(p1, p2);
}

return mesh;

